import React from "react";
import Stack from "../Stack";
import Toggle from "../Toggle";
import ProgressBar from "./ProgressBar";
import type { Meta, StoryObj } from "@storybook/react";
import withDarkMode from "../../lib/utils/storybookDecorators";

const meta: Meta<typeof ProgressBar> = {
  id: "Components/Progress Bar",
  title: "Components/Progress Bar",
  component: ProgressBar,
};

export default meta;
type Story = StoryObj<typeof ProgressBar>;

export const Basic: Story = {
  tags: ["visual-test"],
  args: {
    value: 25,
  },
  render: (args) => (
    <Stack spacing="2-x" className="w-208">
      <ProgressBar {...args} />
    </Stack>
  ),
};

export const Percentage: Story = {
  render: () => (
    <Stack spacing="2-x" className="w-208">
      <ProgressBar showPercentage />
      <ProgressBar showPercentage value={25} />
      <ProgressBar showPercentage value={100} />
    </Stack>
  ),
};

export const PercentageRight: Story = {
  render: () => (
    <Stack spacing="2-x" className="w-208">
      <ProgressBar showPercentage percentageRight />
      <ProgressBar showPercentage percentageRight value={25} />
      <ProgressBar showPercentage percentageRight value={100} />
    </Stack>
  ),
};

export const WithLabel: Story = {
  render: () => (
    <Stack spacing="2-x" className="w-208">
      <ProgressBar label="Downloading file..." value={25} />
      <ProgressBar label="Downloading file..." showPercentage value={25} />
    </Stack>
  ),
};

export const Callback: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    const [progress, setProgress] = React.useState(0);
    const [called, setCalled] = React.useState(false);
    return (
      <Stack spacing="2-x" className="w-208">
        <ProgressBar
          label="Progress..."
          value={progress}
          onAnimationComplete={() => setCalled(true)}
        />
        <Toggle
          label="0/100%"
          onChange={(_, checked) => {
            if (!checked) setCalled(false);
            setProgress(checked ? 100 : 0);
          }}
        />
        <div>{called ? "callback called" : "waiting for call"}</div>
      </Stack>
    );
  },
};

export const Indeterminate: Story = {
  render: () => (
    <div className="w-208">
      <ProgressBar indeterminate />
    </div>
  ),
};

export const Status: Story = {
  render: () => (
    <Stack spacing="2-x" className="w-208">
      <ProgressBar status="success" label="Success" value={100} />
      <ProgressBar status="warning" label="Warning" value={25} />
      <ProgressBar status="error" label="Error" value={25} />
    </Stack>
  ),
};

export const Dark: Story = {
  tags: ["visual-test"],
  decorators: [withDarkMode],
  render: () => (
    <Stack spacing="2-x" className="w-208">
      <ProgressBar indeterminate />
      <ProgressBar label="Downloading file..." showPercentage value={25} />
      <ProgressBar status="success" label="Success" value={100} />
      <ProgressBar status="warning" label="Warning" value={25} />
      <ProgressBar status="error" label="Error" value={25} />
    </Stack>
  ),
};
